-- Daily quests of the Trưởng Lão (2e-B PR3). Rows are inserted here (not left to the seeding) so every running isolate sees them at once through the version bump.
INSERT OR REPLACE INTO quests (id, chain, seq, enabled, def, updated_at) VALUES ('daily_kill', 'daily', 1, 1, '{"id":"daily_kill","chain":"daily","seq":1,"giver":"elder","titleVi":"Trừ yêu mỗi ngày","descVi":"Yêu thú ở Hắc Mộc Lâm không bao giờ hết. Mỗi ngày hạ 20 con để giữ an toàn cho thành.","enabled":true,"requires":"newbie_3","minRealm":0,"repeat":"daily","objective":{"kind":"kill","count":20,"map":"forest"},"rewards":{"linhThach":150,"congHien":10,"exp":300}}', 0);
INSERT OR REPLACE INTO quests (id, chain, seq, enabled, def, updated_at) VALUES ('daily_herb', 'daily', 2, 1, '{"id":"daily_herb","chain":"daily","seq":2,"giver":"elder","titleVi":"Dược liệu mỗi ngày","descVi":"Mỗi ngày mang cho ta 10 Linh Thảo để luyện đan cho đệ tử trong thành.","enabled":true,"requires":"newbie_3","minRealm":0,"repeat":"daily","objective":{"kind":"collect","item":"linh_thao","qty":10},"rewards":{"linhThach":100,"congHien":8}}', 0);
INSERT OR REPLACE INTO quests (id, chain, seq, enabled, def, updated_at) VALUES ('daily_cave', 'daily', 3, 1, '{"id":"daily_cave","chain":"daily","seq":3,"giver":"elder","titleVi":"Thám hiểm U Minh Động","descVi":"Từ Trúc Cơ trở đi, mỗi ngày hạ 20 con quái ở U Minh Động.","enabled":true,"requires":"newbie_6","minRealm":1,"repeat":"daily","objective":{"kind":"kill","count":20,"map":"cave"},"rewards":{"linhThach":400,"congHien":20}}', 0);
UPDATE config_versions SET version = version + 1, updated_at = 0 WHERE name = 'quests';
